"""D0: additive standard catalogs and links; no prices or permissions."""
TABLES=('catalog_imports','icd10','tech_catalog','shared_lab_codes','official_addresses','occupation_catalog','service_tech_codes')
FIELDS={
 'icd10':"name_vi TEXT NOT NULL,name_en TEXT NOT NULL DEFAULT '',chapter TEXT NOT NULL DEFAULT '',not_primary INTEGER NOT NULL DEFAULT 0,discouraged_primary INTEGER NOT NULL DEFAULT 0,replaced INTEGER NOT NULL DEFAULT 0,replacement_codes TEXT NOT NULL DEFAULT '',death_only INTEGER NOT NULL DEFAULT 0,sex TEXT NOT NULL DEFAULT ''",
 'tech_catalog':"name TEXT NOT NULL,chapter TEXT NOT NULL DEFAULT ''",
 'shared_lab_codes':"name TEXT NOT NULL,tech_code TEXT NOT NULL DEFAULT '',loinc TEXT NOT NULL DEFAULT '',component TEXT NOT NULL DEFAULT '',property TEXT NOT NULL DEFAULT '',timing TEXT NOT NULL DEFAULT '',specimen TEXT NOT NULL DEFAULT '',method TEXT NOT NULL DEFAULT '',unit TEXT NOT NULL DEFAULT ''",
 'official_addresses':"name TEXT NOT NULL,province_name TEXT NOT NULL,province_code TEXT NOT NULL,kind TEXT NOT NULL",
 'occupation_catalog':"name TEXT NOT NULL",
}
def migrate_d0(c,postgres=False):
    if c.execute('SELECT 1 FROM schema_migrations WHERE version=10').fetchone():return
    identity='BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY' if postgres else 'INTEGER PRIMARY KEY AUTOINCREMENT'
    c.execute(f'''CREATE TABLE catalog_imports(id {identity},kind TEXT NOT NULL,document_number TEXT NOT NULL,document_date TEXT NOT NULL,source TEXT NOT NULL,version TEXT NOT NULL,fingerprint TEXT NOT NULL,mapping TEXT NOT NULL,imported_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL)''')
    for table,fields in FIELDS.items():
        c.execute(f'''CREATE TABLE {table}(code TEXT PRIMARY KEY,{fields},search_key TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,version TEXT NOT NULL,import_id INTEGER NOT NULL REFERENCES catalog_imports(id))''')
        c.execute(f'CREATE INDEX idx_d0_{table}_search ON {table}(active,search_key)')
    c.execute('CREATE TABLE service_tech_codes(service_id INTEGER NOT NULL REFERENCES service_catalog(id),tech_code TEXT NOT NULL REFERENCES tech_catalog(code),PRIMARY KEY(service_id,tech_code))')
    for table,fields in {
      'visits':{'primary_icd10':'TEXT REFERENCES icd10(code)','diagnosis_codes':"TEXT NOT NULL DEFAULT '[]'"},
      'lab_tests':{'shared_code':'TEXT REFERENCES shared_lab_codes(code)'},
      'patients':{'official_province_code':'TEXT','official_commune_code':'TEXT','occupation_code':'TEXT REFERENCES occupation_catalog(code)'},
    }.items():
        for name,definition in fields.items():c.execute(f'ALTER TABLE {table} ADD COLUMN {name} {definition}')
    # NULL occupation_code denotes free text not standardized. No old record is guessed.
    c.execute('INSERT INTO schema_migrations(version) VALUES(10)')
